package probecache

import (
	"encoding/json"
	"strings"
)

// realUsage rejects the historical synthetic samples generated by this plugin.
func realUsage(raw []byte, format string) (map[string]any, bool) {
	var obj struct {
		ID    string         `json:"id"`
		Usage map[string]any `json:"usage"`
	}
	if json.Unmarshal(raw, &obj) != nil || strings.HasPrefix(obj.ID, "chatcmpl-cached-") || obj.Usage == nil {
		return nil, false
	}
	in, ok := obj.Usage["input_tokens"].(float64)
	if !ok {
		in, ok = obj.Usage["prompt_tokens"].(float64)
	}
	out, outOK := obj.Usage["output_tokens"].(float64)
	if !outOK {
		out, outOK = obj.Usage["completion_tokens"].(float64)
	}
	if !ok || !outOK || in <= 0 || out < 0 || in != float64(int64(in)) || out != float64(int64(out)) {
		return nil, false
	}
	// Preserve provider-specific usage details when the response protocol matches.
	if format == "responses" && obj.Usage["input_tokens"] != nil || format == "chat_completions" && obj.Usage["prompt_tokens"] != nil {
		return obj.Usage, true
	}
	if format == "responses" {
		return map[string]any{"input_tokens": in, "output_tokens": out, "total_tokens": in + out}, true
	}
	return map[string]any{"prompt_tokens": in, "completion_tokens": out, "total_tokens": in + out}, true
}

// StreamResponse returns only an upstream SSE event that includes real usage.
func StreamResponse(format string, raw string) []byte {
	for _, line := range strings.Split(raw, "\n") {
		line = strings.TrimSpace(line)
		if !strings.HasPrefix(line, "data:") {
			continue
		}
		var event map[string]json.RawMessage
		if json.Unmarshal([]byte(strings.TrimSpace(strings.TrimPrefix(line, "data:"))), &event) != nil {
			continue
		}
		candidate := []byte(nil)
		if format == "responses" {
			var kind string
			_ = json.Unmarshal(event["type"], &kind)
			if kind == "response.completed" {
				candidate = event["response"]
			}
		} else if format == "chat_completions" {
			candidate, _ = json.Marshal(event)
		}
		if _, ok := realUsage(candidate, format); ok {
			return candidate
		}
	}
	return nil
}
